הנה עולם תלת-מימדי מלא ואינטראקטיבי בקובץ HTML יחיד שרץ ישירות בדפדפן:

```html
<!-- file: index.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>עולם תלת-מימדי אינטראקטיבי - BIRGSOL AI</title>
 <style>
 * {
 margin: 0;
 padding: 0;
 box-sizing: border-box;
 user-select: none;
 }

 body {
 overflow: hidden;
 background-color: #87ceeb;
 font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
 }

 #canvas-container {
 width: 100vw;
 height: 100vh;
 display: block;
 }

 #ui {
 position: absolute;
 top: 24px;
 right: 24px;
 color: #ffffff;
 background: rgba(15, 23, 42, 0.75);
 backdrop-filter: blur(12px);
 -webkit-backdrop-filter: blur(12px);
 padding: 20px 24px;
 border-radius: 16px;
 border: 1px solid rgba(255, 255, 255, 0.15);
 box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
 max-width: 320px;
 z-index: 10;
 direction: rtl;
 }

 h1 {
 font-size: 20px;
 font-weight: 700;
 margin-bottom: 12px;
 color: #fbbf24;
 display: flex;
 align-items: center;
 gap: 8px;
 }

 p {
 font-size: 14px;
 line-height: 1.6;
 color: #e2e8f0;
 margin-bottom: 6px;
 }

 .controls-info {
 margin-top: 10px;
 padding-top: 10px;
 border-top: 1px solid rgba(255, 255, 255, 0.1);
 font-size: 13px;
 color: #94a3b8;
 }

 .btn {
 margin-top: 14px;
 width: 100%;
 padding: 10px 16px;
 font-size: 14px;
 font-weight: 600;
 cursor: pointer;
 background: linear-gradient(135deg, #10b981 0%, #059669 100%);
 color: white;
 border: none;
 border-radius: 10px;
 box-shadow: 0 4px 14px rgba(16, 185, 129, 0.4);
 transition: all 0.2s ease-in-out;
 }

 .btn:hover {
 transform: translateY(-2px);
 box-shadow: 0 6px 20px rgba(16, 185, 129, 0.6);
 background: linear-gradient(135deg, #34d399 0%, #10b981 100%);
 }

 .btn:active {
 transform: translateY(0);
 }
 </style>

 <script type="importmap">
 {
 "imports": {
 "three": "https://unpkg.com/three@0.164.1/build/three.module.js",
 "three/addons/": "https://unpkg.com/three@0.164.1/examples/jsm/"
 }
 }
 </script>
</head>
<body>

 <div id="ui">
 <h1>☀️ עולם תלת-מימדי</h1>
 <p>קח שליטה מלאה על המצלמה:</p>
 <div class="controls-info">
 <p>🖱️ <b>גרירה:</b> סיבוב המצלמה במרחב</p>
 <p>🔍 <b>גלגלת:</b> התקרבות והתרחקות (Zoom)</p>
 <p>🖐️ <b>מקש ימני + גרירה:</b> הזזת נקודת המבט</p>
 </div>
 <button class="btn" id="addObjBtn">➕ הוסף צורה אקראית</button>
 </div>

 <div id="canvas-container"></div>

 <script type="module">
 import * as THREE from 'three';
 import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

 // 1. Scene setup
 const container = document.getElementById('canvas-container');
 const scene = new THREE.Scene();
 scene.background = new THREE.Color(0x87ceeb); // שמיים כחולים
 scene.fog = new THREE.FogExp2(0x87ceeb, 0.015); // ערפל עדין לאופק

 // 2. Camera setup
 const camera = new THREE.PerspectiveCamera(
 60,
 window.innerWidth / window.innerHeight,
 0.1,
 1000
 );
 camera.position.set(0, 10, 20);

 // 3. Renderer setup
 const renderer = new THREE.WebGLRenderer({ antialias: true });
 renderer.setSize(window.innerWidth, window.innerHeight);
 renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
 renderer.shadowMap.enabled = true;
 renderer.shadowMap.type = THREE.PCFSoftShadowMap;
 container.appendChild(renderer.domElement);

 // 4. Controls setup
 const controls = new OrbitControls(camera, renderer.domElement);
 controls.enableDamping = true;
 controls.dampingFactor = 0.05;
 controls.maxPolarAngle = Math.PI / 2 - 0.01; // למנוע מעבר מתחת לקרקע
 controls.minDistance = 3;
 controls.maxDistance = 60;
 controls.target.set(0, 2, 0);

 // 5. Lighting
 const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
 scene.add(ambientLight);

 const sunLight = new THREE.DirectionalLight(0xfff5ea, 1.4);
 sunLight.position.set(20, 35, 15);
 sunLight.castShadow = true;
 sunLight.shadow.mapSize.width = 2048;
 sunLight.shadow.mapSize.height = 2048;
 sunLight.shadow.camera.near = 0.5;
 sunLight.shadow.camera.far = 100;
 const d = 25;
 sunLight.shadow.camera.left = -d;
 sunLight.shadow.camera.right = d;
 sunLight.shadow.camera.top = d;
 sunLight.shadow.camera.bottom = -d;
 sunLight.shadow.bias = -0.0005;
 scene.add(sunLight);

 // 6. Visual Sun Mesh
 const sunGeo = new THREE.SphereGeometry(2.5, 32, 32);
 const sunMat = new THREE.MeshBasicMaterial({ color: 0xffdd44 });
 const sunMesh = new THREE.Mesh(sunGeo, sunMat);
 sunMesh.position.copy(sunLight.position);
 scene.add(sunMesh);

 // 7. Ground (קרקע ירוקה)
 const groundGeo = new THREE.PlaneGeometry(120, 120);
 const groundMat = new THREE.MeshStandardMaterial({
 color: 0x4caf50,
 roughness:
 const shapeFactories = [
 () => new THREE.BoxGeometry(1.5, 1.5, 1.5),
 () => new THREE.SphereGeometry(1, 32, 32),
 () => new THREE.ConeGeometry(1, 2, 32),
 () => new THREE.TorusGeometry(0.8, 0.35, 16, 40),
 () => new THREE.TorusKnotGeometry(0.7, 0.25, 100, 16),
 () => new THREE.CylinderGeometry(0.7, 0.7, 1.8, 32),
 () => new THREE.IcosahedronGeometry(1.1)
 ];

 const button = document.createElement('button');
 button.textContent = 'הוסף צורה';
 button.style.position = 'absolute';
 button.style.top = '20px';
 button.style.left = '20px';
 button.style.padding = '10px 20px';
 button.style.fontSize = '16px';
 document.body.appendChild(button);

 button.addEventListener('click', () => {
 const geometry = shapeFactories[Math.floor(Math.random() * shapeFactories.length)]();
 const color = new THREE.Color().setHSL(Math.random(), 0.7, 0.5);
 const material = new THREE.MeshStandardMaterial({
 color: color,
 roughness: Math.random() * 0.5 + 0.25,
 metalness: Math.random() * 0.5
 });
 const mesh = new THREE.Mesh(geometry, material);
 mesh.position.set(
 (Math.random() - 0.5) * 30,
 Math.random() * 5 + 1,
 (Math.random() - 0.5) * 30
 );
 mesh.castShadow = true;
 mesh.receiveShadow = true;
 scene.add(mesh);
 });

 // 11. אנימציה
 function animate() {
 requestAnimationFrame(animate);
 controls.update();
 renderer.render(scene, camera);
 }
 animate();

 // 12. שינוי גודל החלון
 window.addEventListener('resize', () => {
 const width = window.innerWidth;
 const height = window.innerHeight;
 camera.aspect = width / height;
 camera.updateProjectionMatrix();
 renderer.setSize(width, height);
 });
```
